# BFS to get distances, then sort by distance and pick closest 60
def test_closest_k(inp):
    layers = {}
    priority = []
    q = deque()
    for r in range(n):
        for c in range(m):
            if inp[r][c] == 4:
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < n and 0 <= nc < m and inp[nr][nc] == 0:
                        layers[(nr, nc)] = 1
                        priority.append((1, (nr, nc)))
                        q.append((nr, nc))

    while q:
        r, c = q.popleft()
        dist = layers[(r,c)]
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < n and 0 <= nc < m and inp[nr][nc] == 0:
                if (nr, nc) not in layers:
                    layers[(nr, nc)] = dist + 1
                    priority.append((dist + 1, (nr, nc)))
                    q.append((nr, nc))

    # Sort by distance (and by position to break ties deterministically)
    priority.sort()

    result = [[inp[r][c] for c in range(m)] for r in range(n)]
    count = 0
    for _, (r, c) in priority:
        if count >= 60:
            break
        result[r][c] = 4
        count += 1
    return result

