    for rr, cc in comp:
        for ddr, ddc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nnr, ncc = rr+ddr, cc+ddc
            if 0 <= nnr < n and 0 <= ncc < m and inp[nnr][ncc] == 4:
                dist[(rr, cc)] = 0
                queue.append((rr, cc))

    while queue:
        rr, cc = queue.popleft()
        for ddr, ddc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nrr, ncc = rr+ddr, cc+ddc
            if 0 <= nrr < n and 0 <= ncc < m and inp[nrr][ncc] == 0 and (nrr, ncc) in dist:
                if dist[(nrr, ncc)] == float('inf'):
                    dist[(nrr, ncc)] = dist[(rr, cc)] + 1
                    queue.append((nrr, ncc))
    return dist

# For each multi-cell component, test distance patterns
print(f"\nAnalyzing multi-cell components:")
for comp, is_multi in all_comps:
    if len(comp) <= 1:
        continue

    dist_from_4_boundary = bfs_from_4_boundary(comp, inp, n, m)
    zero_to_four = sum(1 for rr,cc in comp if expected[rr][cc] == 4)

    print(f"\nComponent size {len(comp)} at {comp[0]}:")
    print(f"  Interior 0s adjacent to 4: {sum(1 for rr,cc in comp if dist_from_4_boundary[(rr,cc)] == 0)}")

    # For component cells at different distances from 4-adjacent cells
    dist_groups = {}
    for rr, cc in comp:
        d = dist_from_4_boundary[(rr, cc)]
        dist_groups.setdefault(d, [])
        dist_groups[d].append((rr, cc, expected[rr][cc] == 4))

    for d, cells_with_expected in sorted(dist_groups.items()):
        becomes_4 = sum(1 for _,_,e in cells_with_expected if e)
        stays_0 = len(cells_with_expected) - becomes_4
        print(f"  Dist {d}: count={len(cells_with_expected)}, becomes_4={becomes_4}, stays_0={stays_0}")
